mapper.update:
CREATE SEQUENCE ${tableName}_SEQ START WITH 1 MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20;
CREATE INDEX ${tableName}_IDX1 ON ${tableName}(TR_SENDSTAT, TR_SENDDATE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName}(TR_PHONE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName}(TR_SENDDATE, TR_RSLTSTAT);

UPDATE ${tableName}
SET
    TR_SENDSTAT = CASE WHEN TR_SENDSTAT = '2' THEN TR_SENDSTAT ELSE #{parameter.messageStatus} END,
    TR_MODIFIED = NOW()
    , TR_REALSENDDATE = TO_TIMESTAMP(#{parameter.sentDate}, 'YYYYMMDDHH24MISS')
    , TR_RSLTSTAT = #{parameter.doneCode}
    , TR_RSLTDATE = TO_TIMESTAMP(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , TR_ROUTEID = #{parameter.routeId}
    , TR_NET = #{parameter.doneTelco}
WHERE
    TR_NUM IS NULL
    TR_NUM = CAST(#{parameter.key} AS numeric)
